$(function(){const __rebornCheckers=function(){$(".ajax_form, .static_form").each(function(){var __formId=this.id,__form=this;$(".submit",__form).off("click").on("click",function(){let allow=true,__submitButton=this;let var1=$(".req_inpt",__form);$(var1).each(function(){if(isEmpty($(this).val())||$(this).hasClass("email_inpt")&&!isMail($(this).val())){$(this).addClass("fail_input");allow=false}else{$(this).removeClass("fail_input")}});var1=$(".email_inpt",__form);$(var1).each(function(){if($(this).hasClass("req_inpt")){return}if(!isEmpty($(this).val())&&$(this).hasClass("email_inpt")&&!isMail($(this).val())){$(this).addClass("fail_input");allow=false}else{$(this).removeClass("fail_input")}});if(!allow){return false}$(".token",__form).remove();let js_data={};$(".ajax_form_wrapper",__form).wrap("<form></form>");js_data=$("form",__form).serializeJSON();$(__submitButton).data("posted",true).fadeTo(0,.3);js_data["__form__"]=__formId.replace(/_form$/,"");if($(__form).hasClass("static_form")){$("form",__form).trigger("submit");return true}$.ajax({async:true,cache:false,data:js_data,dataType:"html",timeout:8e3,type:"POST",url:$(__form).attr("uri"),error:function(jqXHR,textStatus,errorThrown){$(__submitButton).data("posted",false).fadeTo(0,1)},success:function(data,textStatus,jqXHR){let container=$(__form).parent();$("#"+__formId).html(data);__rebornCheckers()}})})})};__rebornCheckers()});function HideWin(th,speed){if(typeof speed==="undefined"){$(th).hide();$("#overlay").hide()}else{$(th).animate({opacity:"0"},speed,function(){$("#overlay").hide();$(this).hide()})}}function ShowWin(th,speed){if(typeof speed==="undefined"){$("#overlay").center({resize:true});$("#overlay").show();$(th).center().show()}else{$("#overlay").center({resize:true});$("#overlay").show(speed,function(){$(th).css({opacity:"0",display:"block"}).center().animate({opacity:"1"},speed)})}}function ShowFillFormErrorMess(layer,errorHtml){if(errorHtml.trim()===""){return}let html='<div class="alert-errors">';html+=errorHtml;html+="</div>";$(html).insertAfter($(".headess",layer))}function ClearFillFormErrorMess(layer){$(".alert-errors",layer).remove()}